import { readFile } from 'node:fs/promises';
import openapiTS, { astToString } from 'openapi-typescript';
import { describe, expect, it } from 'vitest';

const BANNER = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

describe('generated API client', () => {
  it('matches packages/contract/openapi.json (run `pnpm --filter @tribo/web client`)', async () => {
    const spec = new URL('../../../packages/contract/openapi.json', import.meta.url);
    const expected = BANNER + astToString(await openapiTS(spec));
    const committed = await readFile(new URL('generated/api.d.ts', import.meta.url), 'utf8');
    expect(committed === expected, 'src/generated/api.d.ts is stale').toBe(true);
  });
});
